// Channels that gave permission to clip them. Their uploads playlist is "UU" + the
// rest of the channel ID, and reading it costs 1 quota unit instead of 100 for search.
const ids = String($('Klip ayarları').first().json.allowed_channels || '')
  .split(',').map(s => s.trim()).filter(s => /^UC[A-Za-z0-9_-]{22}$/.test(s));
if (!ids.length) return [{ json: { playlistId: null } }];
return ids.map(id => ({ json: { channelId: id, playlistId: 'UU' + id.slice(2) } }));

// Collect candidate IDs from the three sources, keeping trend order first.
const cfg = $('Klip ayarları').first().json;
const maxAgeMs = Number(cfg.max_age_hours) * 3600e3;
const fresh = iso => iso && Date.now() - Date.parse(iso) <= maxAgeMs;
const rank = {};
const add = (id, source) => { if (id && !(id in rank)) rank[id] = { order: Object.keys(rank).length, source }; };

for (const v of $('Türkiye oyun trendleri').first().json.items || []) add(v.id, 'trend');
for (const v of $('CC lisanslı oyun videoları').first().json.items || []) add(v.id?.videoId, 'cc-search');
for (const it of $input.all()) {
  for (const p of it.json.items || []) if (fresh(p.contentDetails?.videoPublishedAt)) add(p.contentDetails.videoId, 'allowlist');
}
const ids = Object.keys(rank).slice(0, 50);
if (!ids.length) return [];
return [{ json: { ids: ids.join(','), rank } }];

// Choose today's clip source. Only videos we may reuse: Creative Commons licensed, or
// from a channel on the permission list. Skip lives, very short or very long videos,
// anything already clipped, and the channel clipped in the last 24 hours, so the three
// daily Shorts come from different creators.
const cfg = $('Klip ayarları').first().json;
const { rank } = $('Adayları birleştir').first().json;
const allowed = new Set(String(cfg.allowed_channels || '').split(',').map(s => s.trim()).filter(Boolean));
const state = $getWorkflowStaticData('global');
state.used = state.used || [];
state.channels = (state.channels || []).filter(c => Date.now() - c.at < 24 * 3600e3);
const usedIds = new Set(state.used);
const recentChannels = new Set(state.channels.map(c => c.id));

const secs = iso => {
  const m = /P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/.exec(iso || '') || [];
  return (+m[1] || 0) * 86400 + (+m[2] || 0) * 3600 + (+m[3] || 0) * 60 + (+m[4] || 0);
};

const candidates = ($input.first().json.items || [])
  .map(v => ({
    v,
    permission: v.status?.license === 'creativeCommon' ? 'cc' : allowed.has(v.snippet?.channelId) ? 'allowlist' : null,
    length: secs(v.contentDetails?.duration),
    r: rank[v.id] || { order: 999 },
  }))
  .filter(c => c.permission)
  .filter(c => c.v.snippet?.liveBroadcastContent === 'none')
  .filter(c => c.length >= Number(cfg.min_source_seconds) && c.length <= 3 * 3600)
  .filter(c => !usedIds.has(c.v.id) && !recentChannels.has(c.v.snippet.channelId))
  .sort((a, b) => a.r.order - b.r.order || Number(b.v.statistics?.viewCount || 0) - Number(a.v.statistics?.viewCount || 0));

if (!candidates.length) return [];
const c = candidates[0];
state.used = state.used.concat(c.v.id).slice(-1000);
state.channels.push({ id: c.v.snippet.channelId, at: Date.now() });

return [{ json: {
  videoId: c.v.id,
  sourceTitle: c.v.snippet.title,
  channelTitle: c.v.snippet.channelTitle,
  channelId: c.v.snippet.channelId,
  sourceDescription: String(c.v.snippet.description || '').slice(0, 800),
  sourceTags: (c.v.snippet.tags || []).slice(0, 15),
  views: Number(c.v.statistics?.viewCount || 0),
  permission: c.permission,
  foundVia: c.r.source,
} }];

// Trending gaming Reels (Instagram) and Shorts (YouTube) in Turkey, as style examples
// for hooks and captions. Only their wording style is used, never their footage.
const pick = (items, text, views) => items
  .map(i => i.json)
  .filter(x => x && !x.error && text(x))
  .map(x => ({ t: String(text(x)).replace(/\s+/g, ' ').slice(0, 160), v: Number(views(x) || 0) }));
const reels = pick($('Trend oyun Reels (Instagram)').all(), x => x.caption, x => x.videoPlayCount ?? x.videoViewCount ?? x.likesCount);
const shorts = pick($('Trend oyun Shorts (YouTube)').all(), x => x.title, x => x.viewCount);
const top = [...reels.map(r => ({ ...r, s: 'Reels' })), ...shorts.map(r => ({ ...r, s: 'Shorts' }))]
  .sort((a, b) => b.v - a.v)
  .slice(0, 15)
  .map(r => `- [${r.s}, ${r.v} izlenme] ${r.t}`);
return [{ json: { ...$('Videoyu seç').first().json, styleExamples: top.length ? top.join('\n') : '(örnek alınamadı)' } }];

// Parse Claude's copy, add the attribution the licence requires, and hand the overlay
// texts to the render script base64-encoded so no title text ever reaches the shell.
const src = $('Videoyu seç').first().json;
const text = ($input.first().json.content || []).map(c => c.text || '').join('');
const s = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
if (!s.title || !s.hook) throw new Error('Claude yanıtında başlık veya kanca yok: ' + text.slice(0, 200));

const link = `https://youtu.be/${src.videoId}`;
const credit = src.permission === 'cc'
  ? `Kaynak: ${src.channelTitle} (CC BY)`
  : `Kaynak: ${src.channelTitle} (izinli)`;
const attribution = src.permission === 'cc'
  ? `🎮 Orijinal video: "${src.sourceTitle}" – ${src.channelTitle}\n${link}\nCreative Commons Atıf (CC BY) lisansıyla kullanılmıştır.`
  : `🎮 Orijinal video: "${src.sourceTitle}" – ${src.channelTitle}\n${link}\nKanal sahibinin izniyle kullanılmıştır.`;

let title = String(s.title).trim();
if (!/#shorts/i.test(title)) title = (title.length > 90 ? title.slice(0, 90) : title) + ' #Shorts';
const tags = [...new Set([...(s.tags || []), ...src.sourceTags].map(t => String(t).replace(/[<>,]/g, '').trim()).filter(Boolean))].slice(0, 15);
const runId = new Date().toISOString().replace(/[-:]/g, '').replace(/\..*/, '').replace('T', '-');

return [{ json: {
  runDir: `${$('Klip ayarları').first().json.output_dir}/klip-${runId}`,
  title: title.slice(0, 100),
  description: `${String(s.description).trim()}\n\n${attribution}\n\n#Shorts #oyun`,
  tags: tags.join(','),
  hookB64: Buffer.from(String(s.hook).slice(0, 60), 'utf8').toString('base64'),
  creditB64: Buffer.from(credit, 'utf8').toString('base64'),
  peakTextB64: Buffer.from(String(s.peak_text || '').slice(0, 24), 'utf8').toString('base64'),
  endTextB64: Buffer.from(String(s.end_text || 'TEKRAR').slice(0, 14), 'utf8').toString('base64'),
  freezeTextB64: Buffer.from(String(s.freeze_text || 'DUR BİR DAKİKA').slice(0, 24), 'utf8').toString('base64'),
} }];

// make-clip.mjs prints one JSON line at the end of stdout.
const lines = String($input.first().json.stdout || '').trim().split('\n');
return [{ json: JSON.parse(lines[lines.length - 1]) }];

const src = $('Videoyu seç').first().json;
const clip = $('Klip sonucunu oku').first().json;
return [{ json: {
  videoId: $input.first().json.id,
  url: `https://youtube.com/shorts/${$input.first().json.id}`,
  title: $('Metinleri hazırla').first().json.title,
  source: `https://youtu.be/${src.videoId}?t=${Math.floor(clip.start)}`,
  permission: src.permission,
  cut: `${clip.start}s – ${clip.end}s (${clip.duration} sn, yöntem: ${clip.method})`,
} }];
